import java.util.*;
public class ProducerConsumer {static class Buffer{Queue<Integer> q=new LinkedList<>();synchronized void put(int n)throws InterruptedException{while(q.size()==2)wait();q.add(n);System.out.println("Produced "+n);notifyAll();}synchronized int take()throws InterruptedException{while(q.isEmpty())wait();int n=q.remove();System.out.println("Consumed "+n);notifyAll();return n;}}public static void main(String[] args)throws Exception{Buffer b=new Buffer();Thread p=new Thread(()->{try{for(int i=1;i<=5;i++)b.put(i);}catch(InterruptedException e){Thread.currentThread().interrupt();}});Thread c=new Thread(()->{try{for(int i=1;i<=5;i++)b.take();}catch(InterruptedException e){Thread.currentThread().interrupt();}});p.start();c.start();p.join();c.join();}}
